// Banque de questions — examen civique, mention NATURALISATION
// Questions de connaissance : intitulés de la liste officielle publiée par le ministère de l'Intérieur
// (le ministère ne publie pas les réponses : propositions et corrections rédigées pour l'entraînement).
// Mises en situation (s:1) : non publiées officiellement — rédigées sur le modèle de l'examen.
// th = thème, q = question, a = bonne réponse, w = 3 mauvaises réponses, e = explication
(function () {
const THEMES = {
  valeurs: "Principes et valeurs de la République",
  institutions: "Système institutionnel et politique",
  droits: "Droits et devoirs",
  histoire: "Histoire, géographie et culture",
  societe: "Vivre dans la société française"
};
const QUESTIONS = [
// ======================= PRINCIPES ET VALEURS =======================
{th:"valeurs",q:"Complétez les paroles de la Marseillaise : « Allons enfants de la Patrie, le jour de gloire est… »",a:"arrivé",w:["passé","venu","levé"],e:"« Allons enfants de la Patrie, le jour de gloire est arrivé ! »"},
{th:"valeurs",q:"Complétez les paroles de la Marseillaise : « Aux armes, citoyens, formez… »",a:"vos bataillons",w:["vos régiments","vos armées","vos cortèges"],e:"« Aux armes, citoyens, formez vos bataillons ! »"},
{th:"valeurs",q:"Dans le cadre d'un entretien d'embauche, que peut-on demander au candidat ?",a:"Ses diplômes et son expérience professionnelle",w:["Sa religion","S'il a un projet de grossesse","Ses opinions politiques"],e:"L'employeur ne peut poser que des questions liées aux compétences ; demander la religion, une grossesse ou les opinions est discriminatoire."},
{th:"valeurs",q:"Déclarer ses revenus aux services fiscaux est :",a:"Obligatoire chaque année",w:["Facultatif si l'on gagne peu","Obligatoire seulement pour les propriétaires","Obligatoire tous les cinq ans"],e:"La déclaration est annuelle et obligatoire, même si l'on n'est finalement pas imposable."},
{th:"valeurs",q:"En France, les impôts permettent de financer les dépenses publiques. Quelle proposition est correcte ?",a:"Chacun contribue en fonction de ses moyens",w:["Tout le monde paie exactement le même montant","Seuls les salariés paient des impôts","Les impôts financent uniquement l'armée"],e:"DDHC, art. 13 : la contribution commune est répartie « en raison de leurs facultés »."},
{th:"valeurs",q:"La liberté d'association est :",a:"Une liberté garantie, qui permet de créer une association sans autorisation préalable",w:["Une liberté soumise à l'accord du préfet","Réservée aux citoyens français","Interdite aux mineurs dans tous les cas"],e:"Loi du 1er juillet 1901 : une simple déclaration en préfecture suffit pour qu'une association ait la personnalité juridique."},
{th:"valeurs",q:"La liberté d'expression sur les réseaux sociaux en France est :",a:"Garantie, mais encadrée par les mêmes lois que partout ailleurs",w:["Totale : tout peut être publié","Interdite pour parler de politique","Réservée aux journalistes"],e:"Injure, diffamation, harcèlement ou incitation à la haine en ligne sont punis comme hors ligne."},
{th:"valeurs",q:"Lequel de ces prénoms évoque un symbole de la République ?",a:"Marianne",w:["Jeanne","Joséphine","Catherine"],e:"Marianne est la figure allégorique de la République depuis la Révolution."},
{th:"valeurs",q:"Lequel de ces symboles représente la République française ?",a:"Le drapeau bleu, blanc, rouge",w:["La fleur de lys","L'aigle impérial","La couronne royale"],e:"La fleur de lys était le symbole des rois, l'aigle celui de l'Empire."},
{th:"valeurs",q:"Où peut-on voir la devise de la République ?",a:"Sur le fronton des mairies et des écoles publiques",w:["Uniquement à l'Élysée","Sur les églises","Sur les billets en euros"],e:"« Liberté, Égalité, Fraternité » figure aussi sur les pièces françaises et les documents officiels."},
{th:"valeurs",q:"Lesquels sont des symboles officiels de la République française ?",a:"Le drapeau tricolore, la Marseillaise et la devise",w:["Le coq, la baguette et le béret","La tour Eiffel, le Louvre et Versailles","Le bonnet phrygien, la fleur de lys et le lion"],e:"La Constitution (art. 2) cite l'emblème tricolore, l'hymne (la Marseillaise) et la devise."},
{th:"valeurs",q:"Peut-on brûler publiquement un drapeau français ?",a:"Non, l'outrage au drapeau est puni par la loi",w:["Oui, au nom de la liberté d'expression","Oui, si le drapeau nous appartient","Oui, lors d'une manifestation déclarée"],e:"L'outrage public au drapeau tricolore est sanctionné (amende, voire prison s'il est commis en réunion)."},
{th:"valeurs",q:"Quand la Sécurité sociale a-t-elle été établie en France ?",a:"En 1945",w:["En 1905","En 1936","En 1968"],e:"Les ordonnances d'octobre 1945 créent la Sécurité sociale, issue du programme du Conseil national de la Résistance."},
{th:"valeurs",q:"Que commémore la fête nationale du 14 juillet ?",a:"La prise de la Bastille (1789) et la fête de la Fédération (1790)",w:["La fin de la Seconde Guerre mondiale","La naissance de Napoléon Ier","L'armistice de 1918"],e:"Le 8 mai commémore 1945, le 11 novembre l'armistice de 1918."},
{th:"valeurs",q:"Que porte Marianne sur la tête ?",a:"Un bonnet phrygien",w:["Une couronne","Une couronne de lauriers","Un casque"],e:"Le bonnet phrygien, porté par les révolutionnaires, symbolise la liberté."},
{th:"valeurs",q:"Quel symbole peut-on voir sur les maillots de l'équipe de France de football ?",a:"Le coq",w:["La fleur de lys","Marianne","L'aigle"],e:"Le coq gaulois est un emblème traditionnel de la France, très présent dans le sport."},
{th:"valeurs",q:"Quelle est la devise de la République française ?",a:"Liberté, Égalité, Fraternité",w:["Liberté, Égalité, Solidarité","Travail, Famille, Patrie","Unité, Liberté, Justice"],e:"« Travail, Famille, Patrie » était la devise du régime de Vichy (1940-1944)."},
{th:"valeurs",q:"Qu'est-ce que la liberté d'association ?",a:"Le droit de se regrouper librement autour d'un projet commun",w:["L'obligation d'adhérer à un syndicat","Le droit de se regrouper pour ne pas payer d'impôts","Un droit réservé aux entreprises"],e:"Sport, culture, aide aux autres… on peut créer une association ou en quitter une librement."},
{th:"valeurs",q:"Qu'est-ce qu'une liberté ?",a:"Le pouvoir d'agir sans contrainte, dans le respect de la loi et des autres",w:["Le droit de faire tout ce que l'on veut sans limite","Un avantage accordé par le maire","Une obligation fixée par l'État"],e:"Une liberté a toujours des limites : celles qui protègent les droits d'autrui et l'ordre public."},
{th:"valeurs",q:"Sur quel document peut-on voir Marianne ?",a:"Sur les timbres-poste",w:["Sur les billets en euros","Sur le permis de conduire européen","Sur les tickets de métro"],e:"On la trouve aussi sur les pièces de 1, 2 et 5 centimes françaises et sur le logo de l'administration."},
{th:"valeurs",q:"Une des valeurs de la devise républicaine est l'Égalité. Qu'est-ce que cela signifie ?",a:"Tous les citoyens ont les mêmes droits et devoirs devant la loi",w:["Tout le monde doit gagner le même salaire","Tout le monde doit avoir les mêmes opinions","Les citoyens français ont plus de droits que les étrangers sur tout"],e:"Égalité devant la loi « sans distinction d'origine, de race ou de religion » (Constitution, art. 1)."},
{th:"valeurs",q:"Une personne peut-elle changer librement de religion en France ?",a:"Oui, c'est sa liberté de conscience",w:["Non, c'est interdit","Oui, mais avec l'accord du maire","Oui, mais seulement une fois dans sa vie"],e:"On peut croire, ne pas croire, changer de religion ou abandonner toute religion."},
{th:"valeurs",q:"Que peut faire un usager du service public dans une mairie ?",a:"Porter un signe religieux, dans le respect de l'ordre public",w:["Exiger d'être reçu par un agent de la même religion","Refuser un agent parce que c'est une femme","Demander que l'agent retire son badge officiel"],e:"La neutralité s'impose aux agents, pas aux usagers ; mais l'usager ne peut pas choisir son agent selon le sexe ou la religion."},
{th:"valeurs",q:"En France, il est possible pour l'État de financer :",a:"L'entretien de cathédrales et d'églises construites avant 1905 qui lui appartiennent",w:["Le salaire des prêtres et des imams","La construction de nouvelles mosquées","Les cérémonies religieuses"],e:"Depuis 1905, l'État ne salarie ni ne subventionne aucun culte, mais il entretient les édifices dont il est propriétaire."},
{th:"valeurs",q:"En quelle année la loi de séparation des Églises et de l'État a-t-elle été votée ?",a:"1905",w:["1789","1882","1946"],e:"Loi du 9 décembre 1905."},
{th:"valeurs",q:"Que dit la loi de 1905 ?",a:"La République assure la liberté de conscience et ne reconnaît, ne salarie ni ne subventionne aucun culte",w:["Le catholicisme est la religion officielle de la France","Les religions sont interdites en public","Chaque citoyen doit déclarer sa religion à la mairie"],e:"Ce sont ses articles 1 et 2, fondements de la laïcité."},
{th:"valeurs",q:"Que garantit le principe de laïcité ?",a:"La liberté de croire ou de ne pas croire et la neutralité de l'État",w:["L'interdiction de toutes les religions","La supériorité de la religion majoritaire","L'obligation de pratiquer une religion"],e:"La République « respecte toutes les croyances » (Constitution, art. 1)."},
{th:"valeurs",q:"Quel jour célèbre-t-on officiellement la laïcité en France ?",a:"Le 9 décembre",w:["Le 14 juillet","Le 1er mai","Le 4 août"],e:"Date anniversaire de la loi du 9 décembre 1905."},
{th:"valeurs",q:"Quel symbole religieux peut être porté dans une école publique dans le respect de la laïcité ?",a:"Un petit pendentif discret (petite croix, étoile de David, main de Fatma)",w:["Un voile islamique","Une grande croix bien visible","Une kippa"],e:"La loi de 2004 interdit aux élèves les signes « ostensibles » ; les signes discrets restent autorisés."},
{th:"valeurs",q:"Quel terme désigne précisément la haine ou les préjugés contre les Juifs ?",a:"L'antisémitisme",w:["La xénophobie","L'homophobie","L'islamophobie"],e:"La xénophobie vise les étrangers en général."},
{th:"valeurs",q:"Quel texte est considéré comme le texte fondateur de la laïcité ?",a:"La loi de séparation des Églises et de l'État de 1905",w:["Le Code civil de 1804","La Déclaration universelle des droits de l'homme de 1948","Le traité de Rome de 1957"],e:"La Constitution de 1958 a ensuite inscrit la laïcité dans son article 1er."},
{th:"valeurs",q:"Quelle institution française doit rester neutre en matière de religion ?",a:"L'État et ses services publics",w:["Les associations","Les entreprises privées","Les familles"],e:"Mairies, écoles publiques, préfectures, hôpitaux publics : leurs agents sont neutres."},
{th:"valeurs",q:"Qu'est-ce que la laïcité ?",a:"La séparation des religions et de l'État, qui garantit la liberté de conscience",w:["Le rejet de toutes les religions","La religion officielle de la République","L'obligation de cacher sa religion partout"],e:"Elle protège à la fois les croyants et les non-croyants."},
{th:"valeurs",q:"À l'école, la charte de la laïcité permet de :",a:"Rappeler les règles de la laïcité aux élèves et aux familles",w:["Choisir la religion enseignée","Supprimer les cours d'histoire","Autoriser la prière en classe"],e:"Affichée dans les écoles publiques depuis 2013."},
{th:"valeurs",q:"Qui doit respecter et veiller à la neutralité religieuse dans les services publics ?",a:"Les agents publics",w:["Les usagers","Les ministres des cultes","Les associations de quartier"],e:"Un agent public ne peut pas manifester ses convictions religieuses dans l'exercice de ses fonctions."},
{th:"valeurs",q:"Une personne déclare ne croire en aucun dieu. On peut dire :",a:"Qu'elle est athée",w:["Qu'elle est laïque","Qu'elle est croyante","Qu'elle est agnostique pratiquante"],e:"« Laïque » qualifie l'État, pas une personne qui ne croit pas."},

// ======================= INSTITUTIONS =======================
{th:"institutions",q:"Comment est désigné le Premier ministre ?",a:"Il est nommé par le président de la République",w:["Il est élu par les Français","Il est élu par le Sénat","Il est désigné par le Conseil constitutionnel"],e:"Constitution, art. 8."},
{th:"institutions",q:"Qui peut se présenter aux élections présidentielles ?",a:"Un citoyen français d'au moins 18 ans ayant obtenu 500 parrainages d'élus",w:["Toute personne résidant en France depuis 5 ans","Uniquement un ancien Premier ministre","Tout citoyen européen"],e:"Les 500 « présentations » viennent d'élus d'au moins 30 départements différents."},
{th:"institutions",q:"À qui appartient la souveraineté nationale ?",a:"Au peuple",w:["Au président de la République","Au Parlement","Au gouvernement"],e:"« La souveraineté nationale appartient au peuple qui l'exerce par ses représentants et par la voie du référendum » (art. 3)."},
{th:"institutions",q:"Qui est élu lors des élections municipales ?",a:"Les conseillers municipaux",w:["Le préfet","Les députés","Le président du conseil départemental"],e:"Le conseil municipal élit ensuite le maire parmi ses membres."},
{th:"institutions",q:"L'inscription sur les listes électorales est :",a:"Obligatoire (et automatique à 18 ans pour les jeunes recensés)",w:["Interdite avant 21 ans","Payante","Possible seulement l'année d'une élection présidentielle"],e:"Le Code électoral la rend obligatoire, mais aucune sanction n'est prévue ; voter reste un droit."},
{th:"institutions",q:"Quelle condition est nécessaire pour voter aux élections présidentielles ?",a:"Être français, majeur et inscrit sur les listes électorales",w:["Être propriétaire de son logement","Résider en France depuis 10 ans","Avoir un emploi"],e:"Les citoyens européens ne votent qu'aux municipales et aux européennes."},
{th:"institutions",q:"Quelle condition faut-il remplir pour être candidat aux élections municipales ?",a:"Avoir au moins 18 ans et avoir un lien avec la commune (électeur ou contribuable)",w:["Être né dans la commune","Avoir au moins 30 ans","Être fonctionnaire"],e:"Un citoyen de l'UE peut être conseiller municipal, mais pas maire."},
{th:"institutions",q:"Parmi ces autorités, laquelle est élue ?",a:"Le maire",w:["Le préfet","Le recteur d'académie","Le Premier ministre"],e:"Préfet et recteur sont nommés par le gouvernement ; le Premier ministre est nommé par le président."},
{th:"institutions",q:"Quelles sont les fonctions du maire ?",a:"Il dirige la commune, célèbre les mariages et tient l'état civil",w:["Il vote les lois","Il nomme les juges","Il dirige la police nationale du département"],e:"Il est à la fois agent de l'État (état civil, police municipale) et chef de l'exécutif communal."},
{th:"institutions",q:"Une personne sans accès à Internet veut s'inscrire sur les listes électorales. Où peut-elle s'inscrire ?",a:"À la mairie de sa commune",w:["À la préfecture uniquement","Au bureau de poste","Au tribunal"],e:"L'inscription se fait aussi en ligne sur service-public.fr."},
{th:"institutions",q:"À quel âge peut-on devenir électeur ?",a:"18 ans",w:["16 ans","20 ans","21 ans"],e:"La majorité électorale est passée de 21 à 18 ans en 1974."},
{th:"institutions",q:"En France, est-ce obligatoire de voter ?",a:"Non, voter est un droit et un devoir civique, mais pas une obligation",w:["Oui, sous peine d'amende","Oui, sous peine de perdre sa nationalité","Oui, pour les élections présidentielles seulement"],e:"Seuls les grands électeurs des sénatoriales sont obligés de voter."},
{th:"institutions",q:"A-t-on le droit de ne pas respecter une loi ?",a:"Non, la loi s'impose à tous",w:["Oui, si on ne l'a pas votée","Oui, si elle est contraire à sa religion","Oui, si on est en désaccord avec elle"],e:"On peut la contester légalement (pétition, élus, manifestation), mais pas refuser de l'appliquer."},
{th:"institutions",q:"Comment sont désignés les députés ?",a:"Au suffrage universel direct, par les électeurs de leur circonscription",w:["Ils sont nommés par le président","Ils sont élus par les sénateurs","Ils sont tirés au sort"],e:"Élections législatives, tous les 5 ans (sauf dissolution)."},
{th:"institutions",q:"Qui vote les lois ?",a:"Le Parlement (Assemblée nationale et Sénat)",w:["Le président de la République","Le Conseil constitutionnel","Les préfets"],e:"C'est le pouvoir législatif."},
{th:"institutions",q:"La séparation des pouvoirs est un principe fondamental. Quels sont les trois pouvoirs concernés ?",a:"Législatif, exécutif et judiciaire",w:["Législatif, militaire et religieux","Exécutif, médiatique et judiciaire","Municipal, régional et national"],e:"Faire la loi / l'appliquer / juger."},
{th:"institutions",q:"Qu'est-ce que l'État de droit ?",a:"Un système où tous, y compris l'État, sont soumis aux règles de droit",w:["Un système où le gouvernement peut changer les lois sans vote","Un État où seuls les citoyens doivent respecter la loi","Un État dirigé par des juges"],e:"Il suppose une hiérarchie des normes, l'égalité devant la loi et une justice indépendante."},
{th:"institutions",q:"Quelles sont les durées du mandat du conseil municipal et du maire ?",a:"6 ans",w:["5 ans","4 ans","7 ans"],e:"Les dernières municipales ont eu lieu en mars 2026."},
{th:"institutions",q:"Qui est élu lors des élections législatives ?",a:"Les députés",w:["Les sénateurs","Le président de la République","Les conseillers régionaux"],e:"577 députés siègent à l'Assemblée nationale."},
{th:"institutions",q:"Quelle est la durée du mandat du président de la République ?",a:"5 ans",w:["7 ans","4 ans","6 ans"],e:"Le quinquennat a remplacé le septennat en 2000 (référendum) ; deux mandats consécutifs au maximum."},
{th:"institutions",q:"Quelle est la durée du mandat des députés ?",a:"5 ans",w:["6 ans","4 ans","7 ans"],e:"L'Assemblée peut être dissoute plus tôt par le président."},
{th:"institutions",q:"Quelle est la durée du mandat des sénateurs ?",a:"6 ans",w:["5 ans","9 ans","4 ans"],e:"Le Sénat est renouvelé par moitié tous les 3 ans."},
{th:"institutions",q:"Qui dirige l'action du gouvernement ?",a:"Le Premier ministre",w:["Le président de l'Assemblée nationale","Le président du Sénat","Le ministre de l'Intérieur"],e:"Constitution, art. 21."},
{th:"institutions",q:"En France, est-ce possible d'adhérer à un parti politique ?",a:"Oui, librement",w:["Non, c'est réservé aux élus","Oui, mais seulement au parti du président","Oui, avec l'autorisation du préfet"],e:"Les partis « se forment et exercent leur activité librement » (art. 4)."},
{th:"institutions",q:"Qui sanctionne l'auteur d'un vol ?",a:"Le juge",w:["La victime","Le maire","Le policier qui l'arrête"],e:"La police enquête et interpelle, mais seul un tribunal prononce une peine."},
{th:"institutions",q:"Qui gère les collèges publics ?",a:"Le département",w:["La commune","La région","L'Union européenne"],e:"Commune : écoles ; département : collèges ; région : lycées."},
{th:"institutions",q:"Qui gère les écoles primaires et maternelles publiques ?",a:"La commune",w:["Le département","La région","Le préfet"],e:"La mairie s'occupe des bâtiments, de la cantine et des inscriptions."},
{th:"institutions",q:"Comment sont désignés les maires ?",a:"Ils sont élus par le conseil municipal",w:["Ils sont nommés par le préfet","Ils sont élus directement par les habitants sur un bulletin séparé","Ils sont nommés par le président"],e:"Les habitants élisent les conseillers municipaux, qui élisent le maire."},
{th:"institutions",q:"Quelle collectivité territoriale est responsable des transports régionaux (TER) ?",a:"La région",w:["La commune","Le département","L'État"],e:"La région gère aussi les lycées et le développement économique."},
{th:"institutions",q:"Quelle est l'une des voies possibles pour modifier la Constitution ?",a:"Le référendum",w:["Un décret du Premier ministre","Une décision du maire de Paris","Une circulaire ministérielle"],e:"Autre voie : le vote du Parlement réuni en Congrès, à la majorité des 3/5."},
{th:"institutions",q:"Qui assure l'intérim du président de la République en cas de décès ?",a:"Le président du Sénat",w:["Le Premier ministre","Le président de l'Assemblée nationale","Le ministre de la Justice"],e:"Constitution, art. 7 ; une nouvelle élection est alors organisée."},
{th:"institutions",q:"Quel est le rôle du Conseil constitutionnel ?",a:"Vérifier que les lois respectent la Constitution",w:["Voter le budget","Juger les crimes","Nommer les ministres"],e:"Il contrôle aussi la régularité des élections nationales."},
{th:"institutions",q:"Quelle condition est obligatoire pour se présenter à l'élection présidentielle ?",a:"Recueillir 500 parrainages d'élus",w:["Avoir été député","Avoir au moins 35 ans","Être diplômé de l'ENA"],e:"Il faut aussi être français, avoir 18 ans et ne pas être privé de ses droits civiques."},
{th:"institutions",q:"Combien y a-t-il de départements en France ?",a:"101",w:["95","96","13"],e:"96 en métropole et 5 en outre-mer."},
{th:"institutions",q:"Comment est organisé le découpage administratif de la France ?",a:"En communes, départements et régions",w:["En provinces, comtés et cantons","En États fédérés","En arrondissements uniquement"],e:"Ce sont les trois niveaux de collectivités territoriales."},
{th:"institutions",q:"Qui représente l'État dans un département ?",a:"Le préfet",w:["Le maire du chef-lieu","Le député","Le président du conseil départemental"],e:"Nommé en Conseil des ministres, il veille à l'ordre public et à l'application des lois."},
{th:"institutions",q:"Quel est le rôle du président de la République ?",a:"Veiller au respect de la Constitution et garantir l'indépendance nationale",w:["Voter les lois","Diriger les tribunaux","Gérer les communes"],e:"Il est aussi chef des armées et nomme le Premier ministre."},
{th:"institutions",q:"Quel est le rôle du Premier ministre ?",a:"Diriger l'action du gouvernement",w:["Présider le Conseil des ministres","Commander seul les armées","Promulguer les lois"],e:"Le président préside le Conseil des ministres et promulgue les lois ; le Premier ministre dirige le gouvernement."},
{th:"institutions",q:"Quel est le rôle du Défenseur des droits ?",a:"Défendre les personnes face aux administrations et lutter contre les discriminations",w:["Défendre les accusés devant le tribunal","Défendre le territoire en cas de guerre","Contrôler les comptes de l'État"],e:"Autorité indépendante, saisissable gratuitement ; les avocats défendent les accusés, la Cour des comptes contrôle les comptes."},
{th:"institutions",q:"En quelle année la citoyenneté européenne a-t-elle été créée ?",a:"1992",w:["1957","1979","2004"],e:"Par le traité de Maastricht (1992)."},
{th:"institutions",q:"Qui a composé l'hymne de l'Union européenne ?",a:"Ludwig van Beethoven",w:["Wolfgang Amadeus Mozart","Rouget de Lisle","Antonio Vivaldi"],e:"L'« Ode à la joie », extrait de sa 9e symphonie."},
{th:"institutions",q:"Quand est célébrée la journée de l'Europe ?",a:"Le 9 mai",w:["Le 8 mai","Le 1er janvier","Le 14 juillet"],e:"En souvenir de la déclaration Schuman du 9 mai 1950."},
{th:"institutions",q:"Où est le siège de la Banque centrale européenne ?",a:"À Francfort",w:["À Bruxelles","À Paris","À Luxembourg"],e:"La BCE gère l'euro et fixe les taux directeurs."},
{th:"institutions",q:"Où est le siège de la Commission européenne ?",a:"À Bruxelles",w:["À Strasbourg","À Francfort","À Genève"],e:"Genève n'est pas dans l'UE (Suisse)."},
{th:"institutions",q:"Qui siège au Parlement européen ?",a:"Des députés élus par les citoyens des pays de l'UE",w:["Les chefs d'État européens","Des ministres nommés par chaque pays","Des juges européens"],e:"Les chefs d'État se réunissent au Conseil européen."},
{th:"institutions",q:"Combien d'États font partie de l'Union européenne au 1er janvier 2025 ?",a:"27",w:["28","25","30"],e:"28 avant le départ du Royaume-Uni en 2020."},
{th:"institutions",q:"En quelle année le traité de Maastricht, qui marque la fondation de l'Union européenne, a-t-il été signé ?",a:"1992",w:["1957","1986","2002"],e:"Signé le 7 février 1992."},
{th:"institutions",q:"Quel traité concerne la construction de l'Union européenne ?",a:"Le traité de Maastricht",w:["Le traité de Versailles","Le traité de l'Atlantique Nord","Le traité de Vienne"],e:"Versailles (1919) a terminé la Première Guerre mondiale ; l'Atlantique Nord a créé l'OTAN."},
{th:"institutions",q:"Quel État a quitté l'Union européenne en 2020 ?",a:"Le Royaume-Uni",w:["La Suisse","La Norvège","L'Irlande"],e:"Le Brexit ; la Suisse et la Norvège n'ont jamais été membres."},
{th:"institutions",q:"Quel est l'hymne de l'Union européenne ?",a:"L'Ode à la joie",w:["La Marseillaise","Le Chant des partisans","L'Hymne à l'amour"],e:"Joué sans paroles, pour n'avantager aucune langue."},
{th:"institutions",q:"De quoi est composé le drapeau européen ?",a:"De 12 étoiles dorées disposées en cercle sur fond bleu",w:["De 27 étoiles, une par pays","De 12 étoiles blanches sur fond rouge","D'un cercle d'étoiles autour d'un aigle"],e:"Le nombre 12 ne change pas : c'est un symbole d'unité et de perfection."},
{th:"institutions",q:"Qui élit les députés européens ?",a:"Les citoyens de l'Union européenne",w:["Les députés nationaux","Les chefs d'État","La Commission européenne"],e:"Au suffrage universel direct, tous les 5 ans."},
{th:"institutions",q:"Où est le siège du Parlement européen ?",a:"À Strasbourg",w:["À Bruxelles","À Paris","À Francfort"],e:"Les sessions plénières ont lieu à Strasbourg."},

// ======================= DROITS ET DEVOIRS =======================
{th:"droits",q:"À quoi sert le droit de grève ?",a:"À défendre ses intérêts professionnels en cessant collectivement le travail",w:["À ne plus travailler sans perdre son salaire","À bloquer l'entreprise par la force","À prendre des congés supplémentaires"],e:"Les jours de grève ne sont pas payés."},
{th:"droits",q:"Au nom de quoi l'État justifie-t-il la restriction des droits ?",a:"De l'ordre public et de la protection des droits d'autrui",w:["Des convictions religieuses des dirigeants","Des intérêts d'un parti politique","De la volonté du préfet seul"],e:"Une restriction doit être prévue par la loi, nécessaire et proportionnée."},
{th:"droits",q:"Laquelle de ces citations est inscrite dans la Déclaration des droits de l'homme et du citoyen de 1789 ?",a:"« Les hommes naissent et demeurent libres et égaux en droits »",w:["« Liberté, Égalité, Fraternité »","« L'État, c'est moi »","« La France est une République indivisible, laïque, démocratique et sociale »"],e:"Article 1er de la DDHC ; la dernière phrase est l'article 1er de la Constitution de 1958."},
{th:"droits",q:"L'article 4 de la DDHC affirme que « la liberté consiste à pouvoir faire tout ce qui ne nuit pas à autrui ». Qu'est-ce que cela signifie ?",a:"Ma liberté s'arrête là où elle porte atteinte à celle des autres",w:["Je peux faire tout ce que je veux","Je dois demander l'autorisation avant chaque action","La liberté est réservée aux citoyens français"],e:"Les limites de la liberté sont fixées par la loi."},
{th:"droits",q:"Que dit l'article 1er de la Constitution française ?",a:"La France est une République indivisible, laïque, démocratique et sociale",w:["La langue de la République est le français","La souveraineté nationale appartient au peuple","Les hommes naissent libres et égaux en droits"],e:"La langue est à l'art. 2, la souveraineté à l'art. 3, la dernière phrase vient de la DDHC."},
{th:"droits",q:"Que garantit la liberté de la presse ?",a:"Le droit de publier et d'informer sans autorisation préalable",w:["Le droit de publier de fausses accusations sans risque","Le contrôle des journaux par le gouvernement","L'obligation pour chacun d'acheter un journal"],e:"Loi du 29 juillet 1881 ; la diffamation reste punie."},
{th:"droits",q:"Que permet la liberté de circulation ?",a:"De se déplacer librement et de choisir son lieu de résidence",w:["D'entrer dans n'importe quel logement","De circuler sans respecter le code de la route","De passer toutes les frontières sans papiers"],e:"Dans l'espace Schengen, les contrôles aux frontières intérieures sont en principe supprimés."},
{th:"droits",q:"Que signifie être citoyen d'un État ?",a:"Avoir sa nationalité, avec des droits (voter) et des devoirs (respecter les lois)",w:["Habiter dans une grande ville","Payer un loyer","Être né dans le pays"],e:"La citoyenneté donne notamment les droits civils et politiques."},
{th:"droits",q:"Que sont les droits fondamentaux ?",a:"Les droits essentiels garantis à toute personne (dignité, liberté, égalité…)",w:["Des droits réservés aux élus","Des avantages fiscaux","Les règles du code de la route"],e:"Ils sont protégés par la Constitution et par la Convention européenne des droits de l'homme."},
{th:"droits",q:"Quel droit protège une personne contre une arrestation arbitraire ?",a:"Le droit à la sûreté",w:["Le droit de propriété","Le droit de grève","Le droit d'association"],e:"DDHC, art. 7 : nul ne peut être arrêté que dans les cas prévus par la loi."},
{th:"droits",q:"Quel est le texte fondateur établissant les droits et les devoirs de chaque citoyen ?",a:"La Déclaration des droits de l'homme et du citoyen de 1789",w:["Le Code de la route","Le traité de Maastricht","Le Code du travail"],e:"Elle fait partie du « bloc de constitutionnalité »."},
{th:"droits",q:"Quel texte affirme que tous les hommes naissent libres et égaux en droits ?",a:"La Déclaration des droits de l'homme et du citoyen",w:["La loi de 1905","Le Code civil","La Charte de l'environnement"],e:"Adoptée le 26 août 1789."},
{th:"droits",q:"Quelle situation est une atteinte à la dignité humaine ?",a:"Faire travailler quelqu'un sans le payer en lui confisquant son passeport",w:["Refuser une promotion pour manque d'expérience","Payer un loyer élevé","Travailler le samedi"],e:"C'est de la traite des êtres humains, sévèrement punie."},
{th:"droits",q:"Qu'est-ce que la liberté d'expression ?",a:"Le droit de dire et publier ses opinions, dans les limites fixées par la loi",w:["Le droit d'insulter qui l'on veut","Le droit de s'exprimer seulement en français","Le droit réservé aux journalistes"],e:"DDHC, art. 11."},
{th:"droits",q:"Suite à une interpellation par la police, il est possible de :",a:"Demander l'assistance d'un avocat",w:["Refuser de décliner son identité sans conséquence","Partir quand on le souhaite pendant la garde à vue","Exiger d'être jugé immédiatement par le policier"],e:"En garde à vue, on a aussi le droit de se taire et de faire prévenir un proche."},
{th:"droits",q:"Tous les citoyens français ont-ils une religion ?",a:"Non, chacun est libre d'en avoir une ou non",w:["Oui, la religion catholique","Oui, chacun doit en déclarer une","Oui, celle de ses parents"],e:"La liberté de conscience inclut le droit de ne pas croire."},
{th:"droits",q:"À quel âge est fixée la majorité numérique en France ?",a:"15 ans",w:["13 ans","18 ans","16 ans"],e:"Loi de 2023 : avant 15 ans, l'accord d'un parent est requis pour s'inscrire sur un réseau social."},
{th:"droits",q:"Dans lequel de ces endroits est-on autorisé à fumer ?",a:"Chez soi",w:["Dans un restaurant","Dans une gare couverte","Dans un bureau partagé"],e:"Il est interdit de fumer dans les lieux publics fermés, et désormais aussi dans de nombreux espaces extérieurs (parcs, plages, abords des écoles)."},
{th:"droits",q:"En France, la conduite d'une moto sans permis est :",a:"Un délit",w:["Une simple contravention","Autorisée en campagne","Autorisée pour les moins de 125 cm³ sans aucune formation"],e:"Punie d'un an de prison et de 15 000 € d'amende au maximum."},
{th:"droits",q:"En quoi consiste le devoir de solidarité ?",a:"Contribuer, selon ses moyens, à aider les personnes en difficulté",w:["Prêter de l'argent à ses voisins","Donner obligatoirement à une association","Héberger toute personne qui le demande"],e:"Par les impôts et cotisations (santé, retraites, chômage) et par l'entraide."},
{th:"droits",q:"Est-ce légal d'être marié à plusieurs personnes en même temps ?",a:"Non, la polygamie est interdite en France",w:["Oui, si toutes les personnes sont d'accord","Oui, si le mariage a eu lieu à l'étranger","Oui, avec l'accord du maire"],e:"Un nouveau mariage n'est possible qu'après la dissolution du précédent."},
{th:"droits",q:"Est-ce obligatoire de déclarer ses revenus chaque année en France ?",a:"Oui, même si l'on n'est pas imposable",w:["Non, seulement si l'on gagne plus de 30 000 €","Non, c'est l'employeur qui le fait à notre place sans exception","Oui, mais seulement pour les étrangers"],e:"Le prélèvement à la source ne dispense pas de la déclaration annuelle."},
{th:"droits",q:"Est-il obligatoire de porter secours à une personne en danger ?",a:"Oui, si on peut le faire sans se mettre en danger",w:["Non, c'est le travail des pompiers uniquement","Seulement si on la connaît","Seulement si on est médecin"],e:"La non-assistance à personne en danger est un délit ; appeler le 15, 18 ou 112 suffit souvent."},
{th:"droits",q:"Être juré d'assises est :",a:"Un devoir civique obligatoire, sauf motif grave",w:["Une activité réservée aux avocats","Un métier rémunéré à plein temps","Facultatif"],e:"Les jurés sont tirés au sort sur les listes électorales ; un refus injustifié est puni d'une amende."},
{th:"droits",q:"La vente d'alcool en France est interdite aux personnes de moins de :",a:"18 ans",w:["16 ans","21 ans","15 ans"],e:"Le vendeur peut demander une pièce d'identité."},
{th:"droits",q:"Le non-respect du code de la route est :",a:"Une infraction sanctionnée (amende, retrait de points, voire prison)",w:["Une simple impolitesse","Autorisé la nuit","Sanctionné uniquement pour les étrangers"],e:"Selon la gravité : contravention ou délit."},
{th:"droits",q:"Lequel de ces crimes ou délits peut entraîner la privation des droits civils et politiques par un juge ?",a:"La fraude électorale",w:["Un stationnement gênant","Un excès de vitesse de 10 km/h","Un retard de paiement de loyer"],e:"La privation des droits civiques est une peine complémentaire pour certaines infractions graves."},
{th:"droits",q:"Pour obtenir une carte nationale d'identité, il faut :",a:"Être de nationalité française",w:["Être propriétaire","Résider en France depuis 5 ans, quelle que soit sa nationalité","Avoir un emploi"],e:"Les étrangers ont un titre de séjour, pas une carte nationale d'identité."},
{th:"droits",q:"Pour quel motif peut-on limiter la liberté d'expression ?",a:"Pour sanctionner l'incitation à la haine ou à la violence",w:["Pour interdire de critiquer le gouvernement","Pour interdire l'humour","Pour interdire de défendre une opinion minoritaire"],e:"La critique des dirigeants est libre ; l'injure, la diffamation et l'incitation à la haine ne le sont pas."},
{th:"droits",q:"Que doit faire un citoyen appelé à être juré dans un procès d'assises ?",a:"Se présenter au tribunal aux dates indiquées",w:["Envoyer quelqu'un à sa place","Ignorer la convocation","Choisir lui-même l'affaire qu'il veut juger"],e:"Seul un motif grave (santé…) peut dispenser."},
{th:"droits",q:"Quel est l'âge de la majorité civile en France ?",a:"18 ans",w:["16 ans","20 ans","21 ans"],e:"Depuis 1974."},
{th:"droits",q:"Quel est l'un des devoirs principaux d'un citoyen français ?",a:"Respecter les lois",w:["Adhérer à un parti politique","Pratiquer une religion","Faire partie d'une association"],e:"Autres devoirs : payer ses impôts, participer à la défense (JDC), être juré si on est tiré au sort."},
{th:"droits",q:"Quelle est l'infraction la plus grave ?",a:"Le crime",w:["Le délit","La contravention","L'incivilité"],e:"Contravention < délit < crime (jugé par la cour d'assises ou la cour criminelle)."},
{th:"droits",q:"Qu'est-ce que la citoyenneté numérique ?",a:"Utiliser Internet de façon responsable, en respectant la loi et les autres",w:["Voter uniquement en ligne","Avoir une adresse e-mail officielle","Posséder un smartphone"],e:"Protéger ses données, vérifier ses sources, refuser le cyberharcèlement…"},
{th:"droits",q:"Qu'est-ce que le devoir de mémoire ?",a:"Se souvenir des événements tragiques du passé pour qu'ils ne se reproduisent pas",w:["Apprendre par cœur la Constitution","Garder ses papiers d'identité toute sa vie","Connaître la date de naissance des présidents"],e:"Par exemple la Shoah, l'esclavage, les guerres mondiales."},
{th:"droits",q:"Une personne est privée de ses droits civils et politiques pendant 5 ans suite à une condamnation. Laquelle de ces propositions est correcte ? Pendant 5 ans…",a:"Elle ne peut ni voter ni se présenter à une élection",w:["Elle ne peut plus travailler","Elle ne peut plus se marier","Elle perd sa nationalité"],e:"Elle ne peut pas non plus être jurée ni exercer une fonction publique."},

// ======================= HISTOIRE, GÉOGRAPHIE, CULTURE =======================
{th:"histoire",q:"Parmi ces textes, lequel a été adopté sous Napoléon Ier ?",a:"Le Code civil",w:["La Déclaration des droits de l'homme et du citoyen","La loi de 1905","La Constitution de 1958"],e:"Code civil de 1804, toujours en vigueur (modifié)."},
{th:"histoire",q:"Qui a été président de la Ve République ?",a:"Jacques Chirac",w:["Napoléon III","Jules Ferry","Jean Jaurès"],e:"Président de 1995 à 2007 ; de Gaulle, Pompidou, Giscard d'Estaing, Mitterrand, Sarkozy, Hollande et Macron l'ont aussi été."},
{th:"histoire",q:"Que signifie la date du 14 juillet pour les Français ?",a:"C'est la fête nationale",w:["C'est la fête du Travail","C'est l'anniversaire de la victoire de 1945","C'est la journée de l'Europe"],e:"En souvenir de la prise de la Bastille (1789)."},
{th:"histoire",q:"Lequel de ces pays est un pays fondateur de l'Union européenne ?",a:"La Belgique",w:["L'Espagne","Le Royaume-Uni","L'Autriche"],e:"Les 6 fondateurs : France, Allemagne, Italie, Belgique, Pays-Bas, Luxembourg."},
{th:"histoire",q:"Dans quelle région sont situées les plages du débarquement du 6 juin 1944 ?",a:"En Normandie",w:["En Bretagne","En Provence","Dans les Hauts-de-France"],e:"Un second débarquement a eu lieu en Provence le 15 août 1944."},
{th:"histoire",q:"Dans quelle ville les rois de France étaient-ils couronnés ?",a:"Reims",w:["Paris","Versailles","Orléans"],e:"Dans la cathédrale de Reims, comme Charles VII en 1429 avec Jeanne d'Arc."},
{th:"histoire",q:"Quel roi de France a été guillotiné pendant la Révolution française ?",a:"Louis XVI",w:["Louis XIV","Louis XV","Charles X"],e:"Exécuté le 21 janvier 1793."},
{th:"histoire",q:"En quelle année a débuté la Révolution française ?",a:"1789",w:["1793","1815","1848"],e:"Prise de la Bastille le 14 juillet 1789."},
{th:"histoire",q:"En quelle année Napoléon Ier est-il devenu empereur ?",a:"1804",w:["1799","1815","1789"],e:"En 1799, il prend le pouvoir comme Premier consul ; il est sacré empereur en 1804."},
{th:"histoire",q:"Lequel de ces personnages a un lien avec la République française ?",a:"Marianne",w:["Jeanne d'Arc","Clovis","Charlemagne"],e:"Les trois autres sont des figures de la monarchie ou du Moyen Âge."},
{th:"histoire",q:"De quand date l'appel à la Résistance du général de Gaulle ?",a:"Du 18 juin 1940",w:["Du 6 juin 1944","Du 8 mai 1945","Du 3 septembre 1939"],e:"Lancé depuis Londres sur la BBC."},
{th:"histoire",q:"Qu'est-ce que la Shoah ?",a:"Le génocide des Juifs d'Europe par les nazis pendant la Seconde Guerre mondiale",w:["Une bataille de la Première Guerre mondiale","Une fête religieuse","Le nom d'un traité de paix"],e:"Environ 6 millions de Juifs ont été assassinés."},
{th:"histoire",q:"Quel pays a été une colonie française ?",a:"Le Sénégal",w:["Le Brésil","L'Inde","L'Égypte"],e:"Le Sénégal est indépendant depuis 1960 ; l'Inde était britannique, le Brésil portugais."},
{th:"histoire",q:"Depuis quand les Français élisent-ils le président de la République au suffrage universel direct ?",a:"Depuis 1962 (première élection en 1965)",w:["Depuis 1958","Depuis 1945","Depuis 1981"],e:"Réforme voulue par de Gaulle et adoptée par référendum."},
{th:"histoire",q:"En quelle année l'Union européenne a-t-elle été fondée ?",a:"1992",w:["1957","1951","2002"],e:"Traité de Maastricht ; 1957 = traité de Rome (CEE), 1951 = CECA."},
{th:"histoire",q:"Quand a eu lieu la Seconde Guerre mondiale ?",a:"De 1939 à 1945",w:["De 1914 à 1918","De 1940 à 1944","De 1936 à 1942"],e:"1940-1944, c'est la période d'occupation de la France."},
{th:"histoire",q:"Quand a eu lieu la Première Guerre mondiale ?",a:"De 1914 à 1918",w:["De 1939 à 1945","De 1870 à 1871","De 1912 à 1916"],e:"1870-1871 : guerre franco-prussienne."},
{th:"histoire",q:"Sous quel président a été abolie la peine de mort en France ?",a:"François Mitterrand",w:["Valéry Giscard d'Estaing","Charles de Gaulle","Jacques Chirac"],e:"Loi du 9 octobre 1981, portée par Robert Badinter."},
{th:"histoire",q:"Que célèbre-t-on le 8 mai ?",a:"La victoire des Alliés et la fin de la Seconde Guerre mondiale en Europe (1945)",w:["L'armistice de 1918","La prise de la Bastille","La fête du Travail"],e:"Le 11 novembre commémore l'armistice de 1918."},
{th:"histoire",q:"Quelle est la première étape de la construction européenne en 1951 ?",a:"La Communauté européenne du charbon et de l'acier (CECA)",w:["La création de l'euro","L'espace Schengen","Le Parlement européen élu"],e:"Mettre en commun charbon et acier pour rendre la guerre impossible."},
{th:"histoire",q:"Qui était une figure de la Résistance française pendant la Seconde Guerre mondiale ?",a:"Jean Moulin",w:["Philippe Pétain","Georges Clemenceau","Louis Pasteur"],e:"Pétain dirigeait le régime de Vichy qui collaborait avec l'Allemagne."},
{th:"histoire",q:"Le 11 novembre est un jour férié. À quoi correspond cette date ?",a:"À l'armistice de 1918, fin des combats de la Première Guerre mondiale",w:["À la victoire de 1945","À la libération de Paris","À la fin de la guerre d'Algérie"],e:"On y rend hommage à tous les morts pour la France."},
{th:"histoire",q:"Depuis quand l'esclavage est-il définitivement aboli en France ?",a:"Depuis 1848",w:["Depuis 1789","Depuis 1905","Depuis 1945"],e:"Une première abolition en 1794 avait été annulée par Napoléon en 1802."},
{th:"histoire",q:"Qui a aboli l'esclavage en France ?",a:"Victor Schœlcher",w:["Jules Ferry","Napoléon Ier","Jean Jaurès"],e:"Décret du 27 avril 1848 ; il repose au Panthéon."},
{th:"histoire",q:"Depuis quelle année l'école publique est-elle gratuite ?",a:"1881",w:["1905","1789","1945"],e:"Lois Jules Ferry : gratuite (1881), puis obligatoire et laïque (1882)."},
{th:"histoire",q:"En 1944, qu'est-ce qui a changé pour les femmes ?",a:"Elles ont obtenu le droit de vote",w:["Elles ont obtenu le droit de travailler","Elles ont obtenu le droit à l'avortement","Elles ont obtenu le droit d'ouvrir un compte bancaire"],e:"Premier vote en 1945 ; compte bancaire sans l'accord du mari en 1965, IVG en 1975."},
{th:"histoire",q:"Quelle organisation a été créée en 1945 après la Seconde Guerre mondiale ?",a:"L'Organisation des Nations unies (ONU)",w:["L'Union européenne","L'OTAN","La Société des Nations"],e:"L'OTAN date de 1949, la Société des Nations de 1919."},
{th:"histoire",q:"En quelle année l'euro est-il devenu la monnaie de tous les jours en France ?",a:"2002",w:["1992","1981","2008"],e:"Créé en 1999 pour les banques, il circule en pièces et billets depuis le 1er janvier 2002."},
{th:"histoire",q:"Pendant la Seconde Guerre mondiale, quand Paris a-t-il été libéré ?",a:"Le 25 août 1944",w:["Le 6 juin 1944","Le 8 mai 1945","Le 11 novembre 1942"],e:"Par la 2e division blindée du général Leclerc et la Résistance."},
{th:"histoire",q:"Quel était le principal port français impliqué dans la traite négrière au XVIIIe siècle ?",a:"Nantes",w:["Marseille","Brest","Calais"],e:"Bordeaux, La Rochelle et Le Havre y ont aussi participé."},
{th:"histoire",q:"Quel célèbre philosophe des Lumières a dénoncé l'esclavage ?",a:"Montesquieu",w:["Napoléon Bonaparte","Louis XIV","Jules Ferry"],e:"Dans « De l'esprit des lois » (1748) ; Voltaire et Condorcet l'ont aussi dénoncé."},
{th:"histoire",q:"Quel peintre est français ?",a:"Claude Monet",w:["Pablo Picasso","Vincent van Gogh","Rembrandt"],e:"Picasso était espagnol, Van Gogh et Rembrandt néerlandais."},
{th:"histoire",q:"Quel plat est une spécialité de la cuisine française ?",a:"Le bœuf bourguignon",w:["La paella","Le couscous royal","Le goulash"],e:"Spécialité de Bourgogne ; la paella est espagnole, le goulash hongrois."},
{th:"histoire",q:"Qui était Marie Curie ?",a:"Une scientifique, deux fois prix Nobel (physique et chimie)",w:["Une reine de France","Une chanteuse","Une résistante"],e:"Pionnière de la radioactivité ; elle repose au Panthéon."},
{th:"histoire",q:"Qui a peint « La Liberté guidant le peuple » ?",a:"Eugène Delacroix",w:["Claude Monet","Auguste Renoir","Paul Cézanne"],e:"Tableau de 1830 sur la révolution des Trois Glorieuses, exposé au Louvre."},
{th:"histoire",q:"Dans quel grand musée parisien est exposée la Joconde ?",a:"Le musée du Louvre",w:["Le musée d'Orsay","Le Centre Pompidou","Le musée Rodin"],e:"Peinte par Léonard de Vinci."},
{th:"histoire",q:"Quel château célèbre se trouve près de Paris et symbolise le pouvoir royal de Louis XIV ?",a:"Le château de Versailles",w:["Le château de Chambord","Le château de Fontainebleau","Le château d'Amboise"],e:"Chambord et Amboise sont des châteaux de la Loire."},
{th:"histoire",q:"Où peut-on voir des peintures préhistoriques en France ?",a:"Dans la grotte de Lascaux",w:["Au Mont-Saint-Michel","Au château de Versailles","À la cathédrale de Chartres"],e:"En Dordogne ; on visite aujourd'hui une réplique."},
{th:"histoire",q:"Quel peintre célèbre a peint les Nymphéas ?",a:"Claude Monet",w:["Eugène Delacroix","Paul Gauguin","Henri Matisse"],e:"Visibles au musée de l'Orangerie à Paris."},
{th:"histoire",q:"Pendant quelles journées peut-on visiter gratuitement des lieux culturels en France ?",a:"Les Journées européennes du patrimoine",w:["Les jours fériés","La semaine de Noël","Le jour de la fête de la Musique"],e:"Chaque année, le troisième week-end de septembre."},
{th:"histoire",q:"Que symbolise le 1er mai ?",a:"La fête du Travail",w:["La fête nationale","La victoire de 1945","La journée de l'Europe"],e:"Jour férié ; on offre traditionnellement du muguet."},
{th:"histoire",q:"Qui était Rouget de Lisle ?",a:"L'auteur de la Marseillaise",w:["Un roi de France","Un général de Napoléon","Le créateur du drapeau tricolore"],e:"Composée en 1792 à Strasbourg."},
{th:"histoire",q:"À quelle occasion a été construite la tour Eiffel ?",a:"L'Exposition universelle de 1889",w:["Le couronnement de Napoléon","Les Jeux olympiques de 1924","La fin de la Première Guerre mondiale"],e:"Pour le centenaire de la Révolution."},
{th:"histoire",q:"Quelle chaîne de montagnes est située entre la France et l'Italie ?",a:"Les Alpes",w:["Les Pyrénées","Le Jura","Le Massif central"],e:"Les Pyrénées sont entre la France et l'Espagne."},
{th:"histoire",q:"Qui était Molière ?",a:"Un auteur de théâtre du XVIIe siècle",w:["Un peintre impressionniste","Un roi de France","Un scientifique"],e:"« Le Misanthrope », « Le Malade imaginaire »… On parle de « la langue de Molière »."},
{th:"histoire",q:"Qui était Charles Baudelaire ?",a:"Un poète",w:["Un peintre","Un président","Un général"],e:"Auteur des « Fleurs du mal » (1857)."},
{th:"histoire",q:"Qui était George Sand ?",a:"Une romancière du XIXe siècle",w:["Un général américain","Une chanteuse","Une reine"],e:"Elle signait d'un pseudonyme masculin."},
{th:"histoire",q:"Qui était Simone de Beauvoir ?",a:"Une philosophe et écrivaine féministe",w:["Une ministre de la Santé","Une actrice","Une scientifique"],e:"Autrice du « Deuxième Sexe » (1949). À ne pas confondre avec Simone Veil, ministre de la loi sur l'IVG."},
{th:"histoire",q:"Qui était Albert Camus ?",a:"Un écrivain, prix Nobel de littérature",w:["Un président de la République","Un peintre","Un footballeur"],e:"« L'Étranger », « La Peste » ; Nobel en 1957."},
{th:"histoire",q:"Qui était Marguerite Yourcenar ?",a:"Une écrivaine, première femme élue à l'Académie française",w:["Une résistante","Une chanteuse","Une ministre"],e:"Élue en 1980."},
{th:"histoire",q:"Qui était Paul Cézanne ?",a:"Un peintre",w:["Un écrivain","Un architecte","Un homme politique"],e:"Peintre provençal, précurseur de l'art moderne."},
{th:"histoire",q:"Qui était Auguste Rodin ?",a:"Un sculpteur",w:["Un peintre","Un écrivain","Un architecte"],e:"« Le Penseur », « Le Baiser »."},
{th:"histoire",q:"Qui était un célèbre compositeur français ?",a:"Maurice Ravel",w:["Mozart","Beethoven","Vivaldi"],e:"Auteur du « Boléro » ; Debussy et Berlioz sont aussi français."},
{th:"histoire",q:"Qui était Auguste Renoir ?",a:"Un peintre impressionniste",w:["Un sculpteur","Un poète","Un compositeur"],e:"« Le Bal du moulin de la Galette »."},
{th:"histoire",q:"Quel musée est situé à Paris ?",a:"Le musée d'Orsay",w:["Le Prado","Le British Museum","Le musée des Offices"],e:"Le Prado est à Madrid, le British Museum à Londres, les Offices à Florence."},
{th:"histoire",q:"Quel monument historique se trouve sur une île en Normandie ?",a:"Le Mont-Saint-Michel",w:["Le château de Chambord","La cathédrale de Reims","Le pont du Gard"],e:"Abbaye entourée par les marées."},
{th:"histoire",q:"Quelle ville française fait partie des 10 plus grandes métropoles du pays ?",a:"Toulouse",w:["Brest","Ajaccio","Colmar"],e:"Paris, Lyon, Marseille, Toulouse, Lille, Bordeaux, Nice, Nantes…"},
{th:"histoire",q:"Quelle île fait partie des Antilles françaises ?",a:"La Martinique",w:["La Réunion","La Corse","La Nouvelle-Calédonie"],e:"La Guadeloupe aussi ; la Réunion est dans l'océan Indien."},
{th:"histoire",q:"Quelle île est française ?",a:"La Corse",w:["La Sardaigne","La Sicile","Malte"],e:"La Sardaigne et la Sicile sont italiennes, Malte est un État indépendant."},
{th:"histoire",q:"Quelle est la plus haute montagne de France ?",a:"Le mont Blanc",w:["Le mont Ventoux","Le Puy de Dôme","Le Vignemale"],e:"Environ 4 806 m, dans les Alpes."},
{th:"histoire",q:"Quelle île française est située dans l'océan Indien ?",a:"La Réunion",w:["La Martinique","La Guadeloupe","Tahiti"],e:"Mayotte aussi ; Tahiti est dans le Pacifique."},
{th:"histoire",q:"Quel département français a une frontière avec le Brésil ?",a:"La Guyane",w:["La Martinique","La Guadeloupe","Mayotte"],e:"C'est même la plus longue frontière terrestre de la France."},
{th:"histoire",q:"D'où décolle la fusée Ariane ?",a:"De Kourou, en Guyane",w:["De Toulouse","De Cayenne","De Brest"],e:"Le Centre spatial guyanais est proche de l'équateur, ce qui aide les lancements."},
{th:"histoire",q:"Quelle mer ou quel océan borde la France métropolitaine ?",a:"L'océan Atlantique",w:["L'océan Indien","La mer Noire","La mer Baltique"],e:"Aussi la Méditerranée, la Manche et la mer du Nord."},
{th:"histoire",q:"Quelle île est un département d'outre-mer français ?",a:"La Guadeloupe",w:["La Corse","Madagascar","Haïti"],e:"Les 5 DROM : Guadeloupe, Martinique, Guyane, La Réunion, Mayotte."},
{th:"histoire",q:"Qu'est-ce que la France d'outre-mer ?",a:"Les territoires français situés hors du continent européen",w:["Les pays francophones d'Afrique","Les anciennes colonies indépendantes","Les ambassades de France"],e:"Ils font partie de la République."},
{th:"histoire",q:"Quelle est la population approximative de la France en 2025 ?",a:"Environ 68 millions d'habitants",w:["Environ 55 millions","Environ 80 millions","Environ 100 millions"],e:"Environ 68,6 millions au 1er janvier 2025 selon l'Insee."},
{th:"histoire",q:"Quel est le principal port maritime de France ?",a:"Marseille",w:["Nice","Bordeaux","Brest"],e:"Le Havre et Dunkerque sont aussi de très grands ports."},
{th:"histoire",q:"Combien y a-t-il de régions en France métropolitaine ?",a:"13",w:["22","18","101"],e:"18 au total avec les 5 régions d'outre-mer."},
{th:"histoire",q:"Quelle île française se trouve au sud-est du continent africain ?",a:"La Réunion",w:["La Martinique","La Corse","La Guadeloupe"],e:"À l'est de Madagascar."},
{th:"histoire",q:"Quel est le chef-lieu de la région Auvergne-Rhône-Alpes ?",a:"Lyon",w:["Clermont-Ferrand","Grenoble","Saint-Étienne"],e:"Lyon est la 2e ou 3e ville de France selon le critère."},
{th:"histoire",q:"Quel est le chef-lieu de la région Bretagne ?",a:"Rennes",w:["Brest","Nantes","Quimper"],e:"Nantes est le chef-lieu des Pays de la Loire."},
{th:"histoire",q:"Quel est le chef-lieu de la région Provence-Alpes-Côte d'Azur ?",a:"Marseille",w:["Nice","Toulon","Avignon"],e:"Et Toulouse est le chef-lieu de l'Occitanie."},
{th:"histoire",q:"Quel est le 101e département français depuis 2011 ?",a:"Mayotte",w:["La Réunion","La Guyane","La Nouvelle-Calédonie"],e:"La Nouvelle-Calédonie a un statut particulier, ce n'est pas un département."},
{th:"histoire",q:"Quelle région française est réputée pour ses stations de ski ?",a:"Auvergne-Rhône-Alpes",w:["La Bretagne","Les Hauts-de-France","La Normandie"],e:"Les Alpes : Chamonix, Courchevel, Val-d'Isère…"},
{th:"histoire",q:"Quel fleuve traverse Paris ?",a:"La Seine",w:["La Loire","Le Rhône","La Garonne"],e:"La Garonne traverse Toulouse."},

// ======================= VIVRE DANS LA SOCIÉTÉ =======================
{th:"societe",q:"Où faut-il déclarer la naissance d'un enfant ?",a:"À la mairie du lieu de naissance",w:["À la préfecture","À la CAF","Au commissariat"],e:"Souvent directement depuis la maternité."},
{th:"societe",q:"Quelle action peut réaliser le locataire d'un logement sans l'autorisation du propriétaire ?",a:"Repeindre les murs",w:["Abattre une cloison","Sous-louer tout le logement","Construire une véranda"],e:"Les petits aménagements sont libres ; les transformations demandent l'accord écrit du propriétaire."},
{th:"societe",q:"Quel mariage est reconnu légalement ?",a:"Le mariage civil célébré en mairie",w:["Le mariage religieux seul","Le mariage coutumier","Le mariage célébré en ligne"],e:"Le mariage civil doit précéder toute cérémonie religieuse."},
{th:"societe",q:"Le stationnement sur une place réservée aux personnes handicapées sans carte :",a:"Est interdit et puni d'une amende de 135 €",w:["Est autorisé pour 5 minutes","Est autorisé la nuit","Est autorisé si on met ses warnings"],e:"Le véhicule peut aussi être mis en fourrière."},
{th:"societe",q:"Si une machine à laver est cassée, il est possible de :",a:"La déposer à la déchetterie ou la faire reprendre par le vendeur",w:["La laisser sur le trottoir","La jeter dans le conteneur à verre","La déposer dans un bois"],e:"Le vendeur doit reprendre l'ancien appareil quand on en achète un neuf."},
{th:"societe",q:"Dans quel cas faut-il déclarer son enfant au service d'état civil ?",a:"À chaque naissance, dans tous les cas",w:["Seulement si les parents sont mariés","Seulement si l'enfant est français","Seulement s'il naît à l'hôpital"],e:"Déclaration obligatoire pour tout enfant né en France."},
{th:"societe",q:"Quand faut-il déclarer son enfant au service d'état civil ?",a:"Dans les 5 jours qui suivent la naissance",w:["Dans le mois qui suit","Avant ses 1 an","Le jour de son entrée à l'école"],e:"Le jour de l'accouchement n'est pas compté."},
{th:"societe",q:"Quel numéro d'urgence permet d'appeler la police ?",a:"Le 17",w:["Le 15","Le 18","Le 115"],e:"15 : SAMU, 18 : pompiers, 112 : urgence européenne, 115 : hébergement d'urgence."},
{th:"societe",q:"Quel numéro d'urgence permet d'appeler le SAMU ?",a:"Le 15",w:["Le 17","Le 18","Le 119"],e:"Le 119 est le numéro de l'enfance en danger."},
{th:"societe",q:"Auprès de quelle institution les parents peuvent-ils inscrire leurs enfants à l'école publique ?",a:"La mairie",w:["La préfecture","Le rectorat","La CAF"],e:"Puis l'admission se fait auprès du directeur de l'école."},
{th:"societe",q:"En cas de divorce, qui exerce l'autorité parentale ?",a:"Les deux parents, en principe",w:["La mère uniquement","Le père uniquement","Le juge"],e:"Sauf décision contraire du juge, dans l'intérêt de l'enfant."},
{th:"societe",q:"Quelle aide permet aux personnes qui ont des difficultés financières d'avoir un avocat ?",a:"L'aide juridictionnelle",w:["L'allocation de rentrée scolaire","La prime d'activité","L'aide personnalisée au logement"],e:"L'État paie tout ou partie des frais d'avocat selon les revenus."},
{th:"societe",q:"Qui peut demander le divorce de personnes mariées ?",a:"L'un ou l'autre des époux, ou les deux ensemble",w:["Uniquement le mari","Uniquement la femme","Uniquement les parents des époux"],e:"Égalité totale entre les époux."},
{th:"societe",q:"Auprès de quel organisme faut-il demander le remboursement des frais de santé ?",a:"L'Assurance maladie (CPAM)",w:["La CAF","France Travail","La mairie"],e:"La CAF verse les prestations familiales et les aides au logement."},
{th:"societe",q:"La contraception :",a:"Est accessible à toutes et tous, y compris aux mineurs",w:["Est réservée aux personnes mariées","Nécessite toujours l'accord des parents","Est interdite avant 18 ans"],e:"Elle est gratuite pour les moins de 26 ans."},
{th:"societe",q:"À quoi sert la carte Vitale ?",a:"À être remboursé de ses frais de santé par l'Assurance maladie",w:["À prouver sa nationalité","À voter","À payer ses courses"],e:"Elle contient les informations d'affiliation à l'Assurance maladie."},
{th:"societe",q:"À quoi sert une mutuelle santé ?",a:"À compléter les remboursements de l'Assurance maladie",w:["À remplacer la carte Vitale","À payer les impôts","À trouver un médecin"],e:"Les employeurs du privé doivent proposer une mutuelle à leurs salariés."},
{th:"societe",q:"Qu'est-ce que le tiers payant ?",a:"Ne pas avancer les frais de santé : ils sont payés directement au professionnel",w:["Un troisième médecin à consulter","Un impôt sur la santé","Une amende pour rendez-vous manqué"],e:"Très fréquent en pharmacie."},
{th:"societe",q:"L'inscription à l'Assurance maladie est :",a:"Obligatoire",w:["Facultative","Réservée aux salariés","Réservée aux Français"],e:"Toute personne qui travaille ou réside en France de façon stable et régulière est concernée."},
{th:"societe",q:"L'avortement est-il possible en France ?",a:"Oui, c'est une liberté garantie par la Constitution",w:["Non, il est interdit","Oui, mais seulement avec l'accord du père","Oui, mais seulement pour les femmes mariées"],e:"Possible jusqu'à 14 semaines de grossesse ; inscrit dans la Constitution en 2024."},
{th:"societe",q:"Travailler sans être déclaré est :",a:"Illégal",w:["Autorisé si l'employeur et le salarié sont d'accord","Autorisé pendant la période d'essai","Autorisé pour les petits boulots"],e:"C'est du travail dissimulé : pas de droits à la retraite, au chômage ni à l'assurance maladie."},
{th:"societe",q:"Qu'est-ce que le SMIC ?",a:"Le salaire minimum légal",w:["Une aide au logement","Une prime de fin d'année","Le salaire moyen des Français"],e:"Salaire minimum interprofessionnel de croissance, revalorisé chaque année."},
{th:"societe",q:"Quelle est la première démarche à réaliser pour chercher un emploi ?",a:"S'inscrire à France Travail",w:["Demander l'autorisation à la mairie","Faire une demande à la préfecture","S'inscrire sur les listes électorales"],e:"France Travail (ex-Pôle emploi) accompagne et indemnise les demandeurs d'emploi."},
{th:"societe",q:"Quelle est la durée légale du temps de travail par semaine ?",a:"35 heures",w:["39 heures","40 heures","32 heures"],e:"Au-delà, ce sont des heures supplémentaires, payées davantage."},
{th:"societe",q:"Qui peut demander un congé parental d'éducation ?",a:"La mère ou le père",w:["Uniquement la mère","Uniquement le père","Uniquement les grands-parents"],e:"Il faut au moins un an d'ancienneté dans l'entreprise."},
{th:"societe",q:"Une personne étrangère en situation régulière peut-elle créer son entreprise ?",a:"Oui, sous conditions liées à son titre de séjour",w:["Non, jamais","Oui, mais seulement un restaurant","Oui, mais seulement avec un associé français"],e:"Certains titres de séjour l'autorisent directement."},
{th:"societe",q:"Une femme peut-elle créer son entreprise ?",a:"Oui, exactement comme un homme",w:["Oui, avec l'accord de son mari","Non","Seulement dans certains secteurs"],e:"Égalité femmes-hommes."},
{th:"societe",q:"Quels sont les textes qui définissent les règles au travail ?",a:"Le Code du travail et les conventions collectives",w:["Le Code de la route","Le Code civil uniquement","Le règlement de la mairie"],e:"Le contrat de travail et le règlement intérieur s'y ajoutent."},
{th:"societe",q:"Quelles sont les affaires traitées par le conseil de prud'hommes ?",a:"Les litiges entre salariés et employeurs",w:["Les divorces","Les crimes","Les conflits entre voisins"],e:"Licenciement contesté, salaire impayé…"},
{th:"societe",q:"Qui a le droit de se syndiquer ?",a:"Tous les salariés",w:["Seulement les fonctionnaires","Seulement les cadres","Seulement les salariés français"],e:"Aucune sanction ne peut être prise pour appartenance syndicale."},
{th:"societe",q:"Est-il possible de licencier une femme enceinte ou en congé maternité en raison de sa grossesse ?",a:"Non, c'est interdit",w:["Oui, si l'entreprise est petite","Oui, pendant la période d'essai","Oui, si elle a moins d'un an d'ancienneté"],e:"C'est une discrimination ; la salariée est protégée."},
{th:"societe",q:"L'instruction des enfants est obligatoire :",a:"De 3 à 16 ans",w:["De 6 à 16 ans","De 3 à 18 ans","De 6 à 14 ans"],e:"Puis obligation de formation jusqu'à 18 ans."},
{th:"societe",q:"Des parents ne respectent pas l'obligation d'instruction de leurs enfants malgré une mise en demeure. Quelle sanction maximale risquent-ils ?",a:"6 mois de prison et 7 500 € d'amende",w:["Un simple avertissement","Une amende de 35 €","La perte de leur nationalité"],e:"Code pénal, art. 227-17-1."},
{th:"societe",q:"Quelle est la définition de l'autorité parentale ?",a:"L'ensemble des droits et devoirs des parents pour protéger l'enfant jusqu'à sa majorité",w:["Le droit des parents de faire travailler l'enfant","Le pouvoir du père sur toute la famille","Le droit de punir physiquement l'enfant"],e:"Sécurité, santé, moralité, éducation de l'enfant."},
{th:"societe",q:"Quel motif d'absence est accepté par l'école ?",a:"La maladie de l'enfant",w:["Des vacances prolongées","Un rendez-vous chez le coiffeur","Aider ses parents au travail"],e:"Les absences doivent être justifiées par les parents."},
{th:"societe",q:"Jusqu'à quel âge l'instruction est-elle obligatoire ?",a:"16 ans",w:["14 ans","18 ans","15 ans"],e:"Puis obligation de formation jusqu'à 18 ans."},
{th:"societe",q:"À quel âge commence l'instruction obligatoire des enfants ?",a:"3 ans",w:["6 ans","5 ans","2 ans"],e:"Depuis 2019."},
{th:"societe",q:"Comment s'appellent les établissements que les élèves intègrent après l'école élémentaire ?",a:"Les collèges",w:["Les lycées","Les universités","Les maternelles"],e:"Maternelle → élémentaire → collège (11-15 ans) → lycée."},
{th:"societe",q:"En tant que parent d'élève, il est possible de :",a:"Rencontrer les enseignants et élire des représentants de parents",w:["Modifier les notes de son enfant","Choisir le programme scolaire","Assister à tous les cours"],e:"Les représentants participent aux conseils d'école ou de classe."},
{th:"societe",q:"Quelle instruction est prévue pour les enfants qui ne parlent pas français ?",a:"Des cours spécifiques de français dans des classes d'accueil (UPE2A)",w:["Aucune : ils ne peuvent pas aller à l'école","Des cours uniquement dans leur langue maternelle","Une école réservée aux étrangers"],e:"Ils suivent aussi les cours d'une classe ordinaire."},
{th:"societe",q:"S'agissant de l'accueil des enfants en situation de handicap à l'école, laquelle des propositions est vraie ?",a:"Ils ont le droit d'être scolarisés, avec des aménagements si besoin",w:["Ils ne peuvent pas aller à l'école publique","Leurs parents doivent payer l'école","Ils doivent obligatoirement aller dans un établissement spécialisé"],e:"Un AESH (accompagnant) peut les aider en classe."},
{th:"societe",q:"Depuis le 1er juillet 2021, quelle est la durée du congé paternité ?",a:"28 jours (dont 3 jours de congé de naissance)",w:["11 jours","14 jours","3 mois"],e:"Il était de 14 jours (11 + 3) avant 2021."},
{th:"societe",q:"Est-ce possible de punir physiquement ses enfants ?",a:"Non, les violences éducatives sont interdites",w:["Oui, une fessée est autorisée","Oui, si l'enfant a plus de 10 ans","Oui, à la maison seulement"],e:"Loi du 10 juillet 2019."},

// ======================= MISES EN SITUATION =======================
// --- Principes et valeurs
{s:1,th:"valeurs",q:"Lors d'un entretien d'embauche, le recruteur vous demande quelle est votre religion. Que pouvez-vous faire ?",a:"Refuser de répondre : cette question est discriminatoire",w:["Répondre obligatoirement, sinon l'entretien est annulé","Mentir pour avoir le poste, c'est obligatoire","Demander au recruteur sa propre religion"],e:"Seules les compétences peuvent être évaluées ; vous pouvez saisir le Défenseur des droits."},
{s:1,th:"valeurs",q:"Votre voisin dit qu'il ne veut pas que sa fille aille au collège parce que c'est une fille. Que dit la loi ?",a:"L'instruction est obligatoire pour tous les enfants, filles comme garçons",w:["C'est le choix du père","Il suffit de prévenir la mairie","Les filles peuvent arrêter l'école à 12 ans"],e:"Instruction obligatoire de 3 à 16 ans, sans distinction de sexe."},
{s:1,th:"valeurs",q:"Au guichet de la préfecture, l'agent porte une grande croix bien visible sur sa tenue. Est-ce conforme ?",a:"Non, l'agent public doit rester neutre",w:["Oui, c'est sa liberté de religion","Oui, si l'usager est d'accord","Oui, seulement le dimanche"],e:"La neutralité religieuse s'impose aux agents des services publics."},
{s:1,th:"valeurs",q:"Une usagère portant un foulard se présente à la mairie pour faire refaire sa carte d'identité. Que se passe-t-il ?",a:"Elle est reçue normalement ; pour la photo, le visage doit être dégagé",w:["Elle est refusée à cause du foulard","Elle doit revenir avec son mari","Elle doit changer de mairie"],e:"Les usagers peuvent porter un signe religieux ; seules les règles de la photo d'identité s'appliquent."},
{s:1,th:"valeurs",q:"Un parent refuse que son fils soit soigné aux urgences par une femme médecin. Que se passe-t-il ?",a:"Le patient ne peut pas choisir son médecin selon le sexe ; la médecin de garde le soigne",w:["L'hôpital doit trouver un homme médecin","L'enfant n'est pas soigné","Le parent peut exiger un autre hôpital payé par l'État"],e:"Le refus d'un soignant pour son sexe est contraire à l'égalité et au fonctionnement du service public."},
{s:1,th:"valeurs",q:"Un collègue tient en public des propos haineux contre les Juifs. De quoi s'agit-il ?",a:"D'antisémitisme, puni par la loi",w:["D'une simple opinion protégée","D'humour","D'un débat religieux autorisé"],e:"On peut le signaler à sa hiérarchie, à la police ou sur la plateforme PHAROS."},
{s:1,th:"valeurs",q:"Votre propriétaire refuse de vous louer l'appartement parce que vous êtes d'origine étrangère. Que pouvez-vous faire ?",a:"Saisir le Défenseur des droits ou porter plainte pour discrimination",w:["Rien, c'est son droit","Payer un loyer plus élevé","Demander l'autorisation au maire de louer"],e:"Refuser un logement en raison de l'origine est une discrimination punie."},
{s:1,th:"valeurs",q:"Votre enfant de 13 ans veut changer de religion. Que dit la loi ?",a:"La liberté de conscience est protégée ; les parents l'accompagnent dans son éducation",w:["C'est interdit avant 21 ans","Il faut une autorisation de la mairie","Il faut l'accord d'un juge"],e:"Chacun est libre de ses convictions, les parents exercent l'autorité parentale dans l'intérêt de l'enfant."},
{s:1,th:"valeurs",q:"Pendant un cours de sciences, un élève refuse d'étudier un chapitre en invoquant sa religion. Que fait l'enseignant ?",a:"Il rappelle que les programmes sont obligatoires pour tous",w:["Il le dispense de ce chapitre","Il supprime le chapitre pour toute la classe","Il le renvoie définitivement"],e:"La charte de la laïcité interdit de contester un enseignement pour motif religieux."},
{s:1,th:"valeurs",q:"Vous voulez créer une association sportive de quartier. Que devez-vous faire ?",a:"La déclarer en préfecture (ou en ligne) avec ses statuts",w:["Demander l'autorisation au ministre des Sports","Être obligatoirement de nationalité française","Payer une taxe de 1 000 €"],e:"Loi de 1901 : une simple déclaration suffit."},
// --- Institutions
{s:1,th:"institutions",q:"Vous serez en déplacement le jour d'une élection. Comment pouvez-vous voter ?",a:"Donner une procuration à un autre électeur",w:["Voter par SMS","Voter le lendemain","Donner votre carte d'électeur à un ami"],e:"Demande sur maprocuration.gouv.fr, validée au commissariat, à la gendarmerie ou au consulat."},
{s:1,th:"institutions",q:"Vous venez de déménager dans une nouvelle commune. Que faire pour voter aux prochaines élections ?",a:"S'inscrire sur les listes électorales de la nouvelle commune",w:["Rien, l'inscription suit automatiquement","Voter dans l'ancienne commune sans démarche","Demander l'autorisation au préfet"],e:"L'inscription se fait en mairie ou en ligne."},
{s:1,th:"institutions",q:"Vous n'êtes pas d'accord avec une loi votée récemment. Que pouvez-vous faire légalement ?",a:"Signer une pétition, écrire à son député ou manifester de façon déclarée",w:["Refuser de l'appliquer","Bloquer une route sans déclaration","Détruire du matériel public"],e:"En démocratie, on conteste une loi par des moyens légaux."},
{s:1,th:"institutions",q:"Une route de votre commune est dangereuse et vous voulez qu'on installe un ralentisseur. À qui vous adresser ?",a:"À la mairie",w:["Au président de la République","Au Parlement européen","Au tribunal"],e:"La voirie communale relève de la commune."},
{s:1,th:"institutions",q:"Votre fils entre au lycée et le bâtiment est en mauvais état. Quelle collectivité est responsable ?",a:"La région",w:["La commune","Le département","L'Union européenne"],e:"Commune → écoles, département → collèges, région → lycées."},
{s:1,th:"institutions",q:"Vous êtes citoyen italien et vous habitez Toulouse. À quelles élections pouvez-vous voter en France ?",a:"Aux élections municipales et européennes",w:["À l'élection présidentielle","Aux élections législatives","À aucune élection"],e:"C'est un droit lié à la citoyenneté européenne."},
{s:1,th:"institutions",q:"Une administration ne répond plus à vos courriers depuis des mois et bloque votre dossier. Qui pouvez-vous saisir gratuitement ?",a:"Le Défenseur des droits",w:["Le Conseil constitutionnel","La Cour de justice de l'UE","Le président de la République directement"],e:"Ses délégués tiennent des permanences dans chaque département."},
{s:1,th:"institutions",q:"Vous avez été tiré au sort pour être assesseur ou juré. Que faites-vous ?",a:"Je réponds à la convocation, c'est un devoir civique",w:["Je l'ignore","J'envoie un voisin","Je demande à être payé avant de répondre"],e:"Les jurés d'assises sont obligés de siéger sauf motif grave."},
{s:1,th:"institutions",q:"Un candidat aux élections vous propose de l'argent pour voter pour lui. De quoi s'agit-il ?",a:"D'une fraude électorale, punie par la loi",w:["D'une pratique normale","D'un cadeau autorisé","D'une aide sociale"],e:"Acheter des voix peut entraîner prison, amende et privation des droits civiques."},
{s:1,th:"institutions",q:"Le jour du vote, une personne veut entrer dans l'isoloir avec vous pour voir votre bulletin. Que dit la règle ?",a:"Le vote est secret : on passe seul dans l'isoloir",w:["C'est autorisé pour un membre de la famille","C'est obligatoire pour les nouveaux électeurs","C'est autorisé si le président du bureau accepte"],e:"Exception : une personne handicapée peut se faire aider par l'électeur de son choix."},
// --- Droits et devoirs
{s:1,th:"droits",q:"Dans la rue, une personne s'effondre et ne respire plus normalement. Que faites-vous ?",a:"J'appelle le 15 ou le 112 et je suis les consignes",w:["Je continue mon chemin","Je la filme pour les réseaux sociaux","J'attends qu'un policier passe"],e:"Ne pas porter assistance à une personne en danger est un délit."},
{s:1,th:"droits",q:"Vous êtes victime de violences de la part de votre conjoint. Que pouvez-vous faire ?",a:"Porter plainte et appeler le 3919 ou le 17 en cas d'urgence",w:["Rien, c'est une affaire privée","Attendre que cela s'arrête","Demander à la famille de régler le problème"],e:"Les violences conjugales sont des délits, voire des crimes ; le 3919 est gratuit et anonyme."},
{s:1,th:"droits",q:"Quelqu'un publie des insultes contre vous sur les réseaux sociaux tous les jours. Que pouvez-vous faire ?",a:"Faire des captures d'écran et porter plainte pour cyberharcèlement",w:["Rien, Internet n'est pas soumis à la loi","Publier son adresse en représailles","Le menacer à votre tour"],e:"Le cyberharcèlement est un délit ; on peut aussi signaler sur PHAROS ou appeler le 3018."},
{s:1,th:"droits",q:"Un policier vous demande de vous arrêter lors d'un contrôle routier. Que faites-vous ?",a:"Je m'arrête et je présente mes papiers",w:["J'accélère","Je refuse de baisser la vitre","Je filme et je repars"],e:"Le refus d'obtempérer est un délit ; un abus peut être contesté ensuite."},
{s:1,th:"droits",q:"Vous êtes témoin d'une agression dans le tramway. Quelle est la bonne attitude ?",a:"Alerter le conducteur ou appeler le 17, sans me mettre en danger",w:["Ne rien faire","Me battre avec l'agresseur","Prendre une vidéo et la publier"],e:"On peut aussi envoyer un SMS au 114 si on ne peut pas parler."},
{s:1,th:"droits",q:"Vous recevez une convocation pour être juré d'assises, mais vous avez prévu des vacances. Que faites-vous ?",a:"Je me présente : seul un motif grave peut dispenser",w:["Je pars quand même en vacances","J'envoie un certificat de mon employeur","Je réponds que ça ne m'intéresse pas"],e:"Une absence injustifiée est punie d'une amende."},
{s:1,th:"droits",q:"Vous trouvez un portefeuille avec des papiers d'identité dans la rue. Que faites-vous ?",a:"Je le dépose au commissariat, à la gendarmerie ou au service des objets trouvés de la mairie",w:["Je garde l'argent et je jette le reste","Je le laisse par terre","Je le mets en vente"],e:"S'approprier un objet trouvé peut être puni."},
{s:1,th:"droits",q:"Votre voisin organise une fête très bruyante à 2 heures du matin. Que pouvez-vous faire ?",a:"Lui demander poliment de baisser le bruit, puis appeler la police si cela continue",w:["Couper l'électricité de son appartement","Casser sa porte","Faire encore plus de bruit"],e:"Le tapage nocturne est une infraction punie d'une amende."},
{s:1,th:"droits",q:"Vous voulez organiser une manifestation dans votre ville. Que devez-vous faire ?",a:"La déclarer à l'avance en mairie ou en préfecture",w:["Rien, c'est libre sans démarche","Demander l'autorisation au président de la République","Prévenir uniquement les médias"],e:"Déclaration 3 jours francs au moins avant la date."},
{s:1,th:"droits",q:"Votre ami veut conduire après avoir bu plusieurs verres d'alcool. Que dites-vous ?",a:"Je l'en empêche et je lui propose de rentrer autrement",w:["Ce n'est pas mon problème","Il peut conduire s'il roule doucement","Il peut conduire s'il connaît la route"],e:"La conduite en état d'ivresse est un délit et une cause majeure d'accidents mortels."},
// --- Histoire, géographie, culture
{s:1,th:"histoire",q:"Le 11 novembre, votre commune organise une cérémonie devant le monument aux morts. De quoi s'agit-il ?",a:"D'un hommage aux morts pour la France, à l'occasion de l'armistice de 1918",w:["De la fête nationale","De la fête du Travail","D'une fête religieuse"],e:"Le 8 mai, une cérémonie commémore aussi la victoire de 1945."},
{s:1,th:"histoire",q:"Un ami étranger veut voir la grotte de Lascaux et ses peintures préhistoriques. Dans quelle région l'emmenez-vous ?",a:"En Dordogne (Nouvelle-Aquitaine)",w:["En Bretagne","En Alsace","En Corse"],e:"On visite Lascaux IV, une réplique fidèle de la grotte."},
{s:1,th:"histoire",q:"Votre enfant doit faire un exposé sur la femme qui a fait voter la loi sur l'IVG en 1975. Qui est-ce ?",a:"Simone Veil",w:["Simone de Beauvoir","Marie Curie","Olympe de Gouges"],e:"Rescapée d'Auschwitz, elle repose au Panthéon."},
{s:1,th:"histoire",q:"Pour les Journées européennes du patrimoine, vous voulez visiter le palais de l'Élysée. De quoi s'agit-il ?",a:"De la résidence du président de la République",w:["Du siège du Sénat","De la résidence du Premier ministre","Du siège de l'Assemblée nationale"],e:"Le Sénat siège au palais du Luxembourg, l'Assemblée au palais Bourbon, le Premier ministre à Matignon."},
{s:1,th:"histoire",q:"Vous partez en vacances en Martinique. Dans quelle mer se trouve cette île ?",a:"La mer des Caraïbes",w:["L'océan Indien","La mer Méditerranée","L'océan Pacifique"],e:"La Martinique et la Guadeloupe forment les Antilles françaises."},
{s:1,th:"histoire",q:"Le 14 juillet, vous regardez le défilé à la télévision. Sur quelle avenue a-t-il lieu ?",a:"Les Champs-Élysées",w:["La Promenade des Anglais","La Canebière","La rue de Rivoli"],e:"Un défilé militaire a lieu chaque année à Paris."},
{s:1,th:"histoire",q:"Un ami vous demande pourquoi des élèves visitent le mémorial de la Shoah. Que répondez-vous ?",a:"Pour transmettre la mémoire du génocide et lutter contre le racisme et l'antisémitisme",w:["Pour une sortie touristique sans lien avec l'histoire","Pour étudier la géographie de Paris","C'est une obligation religieuse"],e:"C'est le devoir de mémoire."},
{s:1,th:"histoire",q:"Vous voulez voir le tableau « La Liberté guidant le peuple ». Où allez-vous ?",a:"Au musée du Louvre",w:["Au musée d'Orsay","Au château de Versailles","Au Centre Pompidou"],e:"Tableau d'Eugène Delacroix (1830)."},
{s:1,th:"histoire",q:"Vous habitez Toulouse et voulez voir les plages du Débarquement. Dans quelle région allez-vous ?",a:"En Normandie",w:["En Bretagne","En Provence","En Occitanie"],e:"Omaha Beach, Utah Beach, Juno, Gold, Sword."},
{s:1,th:"histoire",q:"Le 1er mai, un ami vous offre un brin de muguet. Que célèbre-t-on ce jour-là ?",a:"La fête du Travail",w:["La fête des Mères","La fête nationale","La victoire de 1945"],e:"Jour férié et chômé."},
// --- Vivre dans la société
{s:1,th:"societe",q:"Vous êtes malade et ne pouvez pas aller travailler. Que devez-vous faire ?",a:"Consulter un médecin et envoyer l'arrêt de travail à l'employeur et à l'Assurance maladie sous 48 h",w:["Ne rien dire","Démissionner","Envoyer un collègue à votre place"],e:"L'arrêt permet de toucher des indemnités journalières."},
{s:1,th:"societe",q:"Votre employeur vous demande de travailler sans contrat et sans fiche de paie. Que dit la loi ?",a:"C'est du travail dissimulé, interdit ; vous pouvez contacter l'inspection du travail",w:["C'est normal pendant l'essai","C'est autorisé si le salaire est élevé","C'est autorisé pour les étudiants"],e:"Sans déclaration, vous n'avez pas de protection sociale."},
{s:1,th:"societe",q:"Votre employeur vous licencie et vous pensez que c'est injustifié. À qui pouvez-vous vous adresser ?",a:"Au conseil de prud'hommes",w:["Au tribunal de commerce","À la préfecture","À la mairie"],e:"Un syndicat ou un avocat peut vous accompagner."},
{s:1,th:"societe",q:"Votre propriétaire ne vous rend pas votre dépôt de garantie sans raison deux mois après votre départ. Que faites-vous ?",a:"Je lui envoie une lettre recommandée, puis je saisis la commission de conciliation ou le juge",w:["J'entre chez lui pour récupérer l'argent","J'arrête de payer mes impôts","Je ne peux rien faire"],e:"Il doit le rendre sous 1 mois (état des lieux conforme) ou 2 mois sinon."},
{s:1,th:"societe",q:"Votre enfant vient de naître à la maternité. Quelle démarche devez-vous faire rapidement ?",a:"Le déclarer à l'état civil de la mairie dans les 5 jours",w:["L'inscrire à l'école","Demander sa carte d'identité","Le déclarer à la CAF uniquement"],e:"L'acte de naissance est indispensable pour toutes les démarches."},
{s:1,th:"societe",q:"Votre enfant de 4 ans n'est pas encore scolarisé. Que dit la loi ?",a:"Il doit être instruit : l'instruction est obligatoire dès 3 ans",w:["L'école est facultative avant 6 ans","Il peut attendre ses 5 ans","C'est au choix de la crèche"],e:"Inscription à la mairie, puis à l'école maternelle."},
{s:1,th:"societe",q:"Vous perdez votre emploi. Quelle est la première démarche ?",a:"M'inscrire à France Travail",w:["Demander le RSA à la mairie","Attendre un appel de mon ancien employeur","M'inscrire sur les listes électorales"],e:"L'inscription ouvre le droit à l'accompagnement et, sous conditions, aux allocations chômage."},
{s:1,th:"societe",q:"Chez le médecin, on vous demande votre carte Vitale. À quoi sert-elle ?",a:"À ce que l'Assurance maladie vous rembourse automatiquement",w:["À prouver votre nationalité","À payer la consultation","À prendre rendez-vous"],e:"Avec une mutuelle, le reste peut aussi être pris en charge."},
{s:1,th:"societe",q:"Vous voyez de la fumée sortir d'un appartement de votre immeuble. Que faites-vous ?",a:"J'appelle le 18 (pompiers) ou le 112",w:["J'attends de voir si ça s'arrête","J'appelle le propriétaire","Je publie une vidéo"],e:"Les pompiers gèrent incendies et secours aux personnes."},
{s:1,th:"societe",q:"Votre fils de 10 ans a de mauvaises notes et vous voulez en parler. Que pouvez-vous faire ?",a:"Demander un rendez-vous à son enseignant",w:["Changer vous-même ses notes","Interdire l'école à votre fils","Insulter l'enseignant devant la classe"],e:"Le dialogue avec l'école fait partie des droits des parents."},
{s:1,th:"societe",q:"Votre collègue enceinte est licenciée juste après avoir annoncé sa grossesse. Que dit la loi ?",a:"C'est une discrimination interdite, elle peut saisir les prud'hommes",w:["C'est autorisé si elle est en CDD","C'est autorisé dans les petites entreprises","C'est normal"],e:"La salariée enceinte bénéficie d'une protection contre le licenciement."},
{s:1,th:"societe",q:"Vous avez besoin d'un avocat mais vos revenus sont faibles. Quelle aide demander ?",a:"L'aide juridictionnelle",w:["L'APL","Le chèque énergie","La prime de Noël"],e:"La demande se fait au tribunal ou en ligne."},
{s:1,th:"societe",q:"Votre machine à laver est cassée et vous en achetez une neuve. Que faire de l'ancienne ?",a:"La faire reprendre par le vendeur ou la déposer à la déchetterie",w:["La laisser sur le trottoir","La jeter dans la poubelle ordinaire","La déposer dans la cour de l'immeuble"],e:"Le dépôt sauvage est puni d'une amende."},
{s:1,th:"societe",q:"Votre conjoint veut punir votre enfant en le frappant. Que dit la loi ?",a:"C'est interdit : les violences éducatives sont proscrites",w:["C'est autorisé à la maison","C'est autorisé si l'enfant a désobéi","C'est autorisé une fois par semaine"],e:"Loi de 2019 ; en cas de danger, le 119 (enfance en danger) peut être appelé."}
];
registerBank("civ", "Examen civique", THEMES, QUESTIONS);
})();
